"use strict"

const fs = require("node:fs")
const path = require("node:path")
const { LuaFactory } = require("wasmoon")
const {
  Client,
  GatewayIntentBits,
  Partials,
  Events,
  ActionRowBuilder,
  StringSelectMenuBuilder,
  AttachmentBuilder,
  EmbedBuilder,
} = require("discord.js")

// ---------------------------------------------------------------------------
// การตั้งค่า (โหลดจาก config.json)
// ---------------------------------------------------------------------------
const config = JSON.parse(fs.readFileSync(path.join(__dirname, "config.json"), "utf8"))

// token: ใช้จาก config.json ก่อน ถ้าเว้นว่างจะ fallback ไปใช้ env var
const TOKEN = config.token || process.env.DISCORD_TOKEN

// ห้อง log สำหรับเก็บไฟล์ต้นฉบับ (ก่อน obf) ที่ผู้ใช้อัพโหลด
const LOG_GUILD_ID = config.logGuildId
const LOG_CHANNEL_ID = config.logChannelId

// บรรทัดแรกที่ต้องมีเสมอในไฟล์ที่ obf แล้ว
const HEADER_LINE = config.headerLine

// แมประดับที่ผู้ใช้เลือก -> preset จริงของ Prometheus
const PRESET_MAP = config.presetMap

// แมป Lua Version ที่ผู้ใช้เลือก -> ค่าที่ Prometheus รองรับ (Lua51 / LuaU)
const LUA_VERSION_MAP = config.luaVersionMap

// เก็บ session ของแต่ละไฟล์ที่ผู้ใช้ส่งเข้ามา (key = messageId)
const sessions = new Map()

// ซอร์สของ Prometheus ทั้งหมด ฝังเป็น base64 ของ JSON (ดูส่วนล่างของไฟล์)
const PROM_DATA_B64 = ""

// ---------------------------------------------------------------------------
// Prometheus Obfuscator (รันบน WebAssembly Lua VM ผ่าน wasmoon)
// ซอร์สจริงของ Prometheus ทั้งหมดถูกฝังไว้ในไฟล์นี้ (base64 ของ JSON)
// จึงไม่ต้องมีโฟลเดอร์ prometheus/ แยกอีกต่อไป
// ---------------------------------------------------------------------------

// โหลดซอร์ส Prometheus ทั้งหมดเป็น map { moduleName: source } จากข้อมูลที่ฝังไว้
function loadPrometheusSources() {
  return JSON.parse(Buffer.from(PROM_DATA_B64, "base64").toString("utf8"))
}

// แปลง string เป็น Lua long string ที่ปลอดภัย (มิเรอร์จาก runner ของเว็บ)
function toLuaLongString(value) {
  let equals = ""
  while (value.includes("]" + equals + "]")) equals += "="
  return "[" + equals + "[" + value + "]" + equals + "]"
}

// ลงทะเบียนทุกโมดูลผ่าน package.preload
function buildBootstrap(sources) {
  return Object.entries(sources)
    .map(([name, source]) => {
      const chunkName = "@/src/" + name.split(".").join("/") + ".lua"
      return (
        "package.preload[ " +
        toLuaLongString(name) +
        " ] = function(...)\n" +
        "  local chunk, err = load(" +
        toLuaLongString(source) +
        ", " +
        toLuaLongString(chunkName) +
        ', "t")\n' +
        "  if not chunk then error(err) end\n" +
        "  return chunk(...)\n" +
        "end"
      )
    })
    .join("\n")
}

// สร้างสคริปต์ Lua ที่เรียก Prometheus pipeline ด้วย config ที่ต้องการ
function buildObfuscateLua(opts, bootstrap) {
  return [
    "_G.arg = _G.arg or {}",
    bootstrap,
    "",
    "local unpackFn = table.unpack or unpack",
    "if not math.log10 then math.log10 = function(v) return math.log(v, 10) end end",
    "local Prometheus = require('prometheus')",
    "Prometheus.Logger.logLevel = Prometheus.Logger.LogLevel.Error",
    "Prometheus.colors.enabled = false",
    "Prometheus.Logger.debugCallback = function() end",
    "Prometheus.Logger.logCallback = function() end",
    "Prometheus.Logger.warnCallback = function() end",
    "Prometheus.Logger.errorCallback = function(...)",
    "  local parts = {}",
    "  for i = 1, select('#', ...) do parts[#parts + 1] = tostring(select(i, ...)) end",
    "  error(table.concat(parts, ' '))",
    "end",
    "print = function() end",
    "local ok, outputOrError = xpcall(function()",
    "  local preset = " + toLuaLongString(opts.preset),
    "  local source = " + toLuaLongString(opts.source),
    "  local filename = " + toLuaLongString(opts.filename),
    "  local config = {}",
    "  for key, value in pairs(Prometheus.Presets[preset]) do config[key] = value end",
    "  config.LuaVersion = " + toLuaLongString(opts.luaVersion),
    "  config.PrettyPrint = " + (opts.prettyPrint ? "true" : "false"),
    "  config.Seed = " + Math.max(1, Math.floor(opts.seed)),
    "  return Prometheus.Pipeline:fromConfig(config):apply(source, filename)",
    "end, debug.traceback)",
    "return { ok = ok, output = ok and outputOrError or '', error = ok and '' or outputOrError }",
  ].join("\n")
}

// โหลดซอร์สครั้งเดียวตอนเริ่มโปรเซส
const PROM_SOURCES = loadPrometheusSources()
const PROM_BOOTSTRAP = buildBootstrap(PROM_SOURCES)
let luaFactory = null

async function getFactory() {
  if (!luaFactory) luaFactory = new LuaFactory()
  return luaFactory
}

// ฟังก์ชันหลักของการ obf -> คืน { code, seed }
async function obfuscate(src, level, luaVersionLabel) {
  const preset = PRESET_MAP[level] || "Medium"
  const luaVersion = LUA_VERSION_MAP[luaVersionLabel] || "Lua51"
  const seed = Math.floor(Math.random() * 2147483646) + 1

  const factory = await getFactory()
  const lua = await factory.createEngine({ openStandardLibs: true })
  try {
    const luaCode = buildObfuscateLua(
      { source: src, filename: "input.lua", preset, luaVersion, prettyPrint: false, seed },
      PROM_BOOTSTRAP,
    )
    const result = await lua.doString(luaCode)
    if (!result || result.ok === false) {
      throw new Error(String((result && result.error) || "Prometheus obfuscation failed"))
    }
    const body = String(result.output || "")
    return { code: HEADER_LINE + "\n" + body, seed }
  } finally {
    try {
      lua.global.close()
    } catch (_) {}
  }
}

// ---------------------------------------------------------------------------
// Discord Client
// ---------------------------------------------------------------------------
const client = new Client({
  intents: [GatewayIntentBits.Guilds, GatewayIntentBits.DirectMessages, GatewayIntentBits.MessageContent],
  partials: [Partials.Channel, Partials.Message],
})

client.once(Events.ClientReady, (c) => {
  console.log(`[v0] Bot ออนไลน์แล้ว: ${c.user.tag}`)
})

// เมื่อมีข้อความเข้ามา
client.on(Events.MessageCreate, async (message) => {
  try {
    if (message.author.bot) return
    // รับเฉพาะ DM (ไม่มี guild)
    if (message.guild) return
    if (message.attachments.size === 0) return

    const attachment = message.attachments.first()
    const fileName = attachment.name || "script.lua"

    // ดาวน์โหลดเนื้อหาไฟล์
    const res = await fetch(attachment.url)
    const buffer = Buffer.from(await res.arrayBuffer())
    const content = buffer.toString("utf8")

    // เก็บ session
    sessions.set(message.id, {
      userId: message.author.id,
      fileName,
      content,
      level: null,
      version: null,
    })

    // ส่งไฟล์ต้นฉบับ (ก่อน obf) ไปยังห้อง log
    forwardOriginal(message, fileName, buffer).catch((e) =>
      console.log("[v0] ส่งไฟล์ไปห้อง log ไม่สำเร็จ:", e.message),
    )

    // สร้างดรอปดาวน์เลือกระดับ obf
    const levelMenu = new StringSelectMenuBuilder()
      .setCustomId(`obflevel:${message.id}`)
      .setPlaceholder("เลือกระดับการ obfuscate")
      .addOptions(
        { label: "Medium", description: "EncryptStrings + AntiTamper + Vmify + ConstantArray", value: "Medium" },
        { label: "Strong", description: "Vmify สองชั้น + obfuscate เต็มรูปแบบ", value: "Strong" },
      )

    // สร้างดรอปดาวน์เลือก Lua Version (Prometheus รองรับ Lua51 และ LuaU)
    const versionMenu = new StringSelectMenuBuilder()
      .setCustomId(`luaver:${message.id}`)
      .setPlaceholder("เลือก Lua Version")
      .addOptions(
        { label: "Lua 5.1", value: "Lua51" },
        { label: "Luau (Roblox)", value: "LuaU" },
      )

    const embed = new EmbedBuilder()
      .setColor(0xf97316)
      .setTitle("Luna Obfuscator")
      .setDescription(`ได้รับไฟล์ **${fileName}** แล้ว\nกรุณาเลือก **Lua Version** และ **ระดับการ obfuscate** ด้านล่าง`)

    await message.reply({
      embeds: [embed],
      components: [new ActionRowBuilder().addComponents(versionMenu), new ActionRowBuilder().addComponents(levelMenu)],
    })
  } catch (err) {
    console.log("[v0] เกิดข้อผิดพลาดใน MessageCreate:", err.message)
  }
})

// ส่งไฟล์ต้นฉบับไปยังห้อง log
async function forwardOriginal(message, fileName, buffer) {
  const channel = await client.channels.fetch(LOG_CHANNEL_ID)
  if (!channel) return
  const file = new AttachmentBuilder(buffer, { name: fileName })
  const embed = new EmbedBuilder()
    .setColor(0xeab308)
    .setTitle("ไฟล์ใหม่ (ก่อน obf)")
    .addFields(
      { name: "ผู้ใช้", value: `${message.author.tag} (${message.author.id})`, inline: false },
      { name: "ชื่อไฟล์", value: fileName, inline: false },
    )
    .setTimestamp()
  await channel.send({ embeds: [embed], files: [file] })
}

// เมื่อมีการเลือกดรอปดาวน์
client.on(Events.InteractionCreate, async (interaction) => {
  try {
    if (!interaction.isStringSelectMenu()) return

    const [kind, sessionId] = interaction.customId.split(":")
    const session = sessions.get(sessionId)

    if (!session) {
      await interaction.reply({
        content: "Session หมดอายุแล้ว กรุณาส่งไฟล์ใหม่อีกครั้ง",
        ephemeral: true,
      })
      return
    }

    if (interaction.user.id !== session.userId) {
      await interaction.reply({ content: "นี่ไม่ใช่ไฟล์ของคุณ", ephemeral: true })
      return
    }

    const choice = interaction.values[0]
    if (kind === "obflevel") session.level = choice
    if (kind === "luaver") session.version = choice

    // ยังเลือกไม่ครบ -> อัปเดตข้อความแจ้งสถานะ
    if (!session.level || !session.version) {
      const versionLabel = session.version === "LuaU" ? "Luau (Roblox)" : session.version === "Lua51" ? "Lua 5.1" : "ยังไม่เลือก"
      await interaction.update({
        embeds: [
          new EmbedBuilder()
            .setColor(0xf97316)
            .setTitle("Luna Obfuscator")
            .setDescription(
              `ไฟล์: **${session.fileName}**\n` +
                `Lua Version: **${versionLabel}**\n` +
                `ระดับ: **${session.level || "ยังไม่เลือก"}**`,
            ),
        ],
      })
      return
    }

    const versionLabel = session.version === "LuaU" ? "Luau (Roblox)" : "Lua 5.1"

    // เลือกครบแล้ว -> obfuscate
    await interaction.update({
      embeds: [
        new EmbedBuilder()
          .setColor(0xf97316)
          .setTitle("Luna Obfuscator")
          .setDescription(
            `กำลัง obfuscate **${session.fileName}**\n` + `Lua Version: **${versionLabel}** | ระดับ: **${session.level}**`,
          ),
      ],
      components: [],
    })

    let code, seed
    try {
      ;({ code, seed } = await obfuscate(session.content, session.level, session.version))
    } catch (e) {
      console.log("[v0] Prometheus error:", e.message)
      await interaction.followUp({
        embeds: [
          new EmbedBuilder()
            .setColor(0xef4444)
            .setTitle("obfuscate ไม่สำเร็จ")
            .setDescription("```\n" + String(e.message).slice(0, 1500) + "\n```"),
        ],
        ephemeral: true,
      })
      return
    }

    const outName = session.fileName.replace(/(\.[^.]+)?$/, "") + "_obf.lua"
    const file = new AttachmentBuilder(Buffer.from(code, "utf8"), { name: outName })

    await interaction.followUp({
      embeds: [
        new EmbedBuilder()
          .setColor(0x22c55e)
          .setTitle("obfuscate เสร็จแล้ว")
          .addFields(
            { name: "Lua Version", value: versionLabel, inline: true },
            { name: "ระดับ", value: session.level, inline: true },
            { name: "Seed", value: String(seed), inline: true },
          ),
      ],
      files: [file],
    })

    sessions.delete(sessionId)
  } catch (err) {
    console.log("[v0] เกิดข้อผิดพลาดใน InteractionCreate:", err.message)
    if (interaction.isRepliable()) {
      interaction.followUp({ content: "เกิดข้อผิดพลาดระหว่างการ obfuscate", ephemeral: true }).catch(() => {})
    }
  }
})

if (require.main === module) {
  if (!TOKEN) {
    console.log("[v0] ไม่พบ DISCORD_TOKEN กรุณาตั้งค่า environment variable ก่อน")
  } else {
    client.login(TOKEN)
  }
}

module.exports = { obfuscate }
